input.content:
// The signature moment.
//
// A buyer cannot tell a £280 knife from a £56 one at the size a product photo
// is printed. So the page does the only thing a photograph cannot: it lets them
// walk up to it. One scroll-driven camera pushes nine times into the blade,
// crossing from a whole-knife frame into a real macro of the same knife at the
// moment the macro can out-resolve the wide shot, and stops on the ground bevel
// where the hand is still visible.

import { useEffect, useRef, useState } from 'react'
import { camera, clamp, FEATURES } from './blade'

const SOURCES = {
  wide: { lg: '/media/blade-wide-4200.webp', sm: '/media/blade-wide-1600.webp' },
  macro: { lg: '/media/blade-macro-2800.webp', sm: '/media/blade-macro-1200.webp' },
}

const REST_PROGRESS = 0.88 // the authored still, for reduced motion

function pickSources() {
  if (typeof window === 'undefined') return { wide: SOURCES.wide.lg, macro: SOURCES.macro.lg }
  const heavy = window.innerWidth > 720
  return {
    wide: heavy ? SOURCES.wide.lg : SOURCES.wide.sm,
    macro: heavy ? SOURCES.macro.lg : SOURCES.macro.sm,
  }
}

export default function Approach() {
  const trackRef = useRef(null)
  const frameRef = useRef(null)
  const wideRef = useRef(null)
  const macroRef = useRef(null)
  const zoomRef = useRef(null)
  const featureRefs = useRef({})
  const stateRef = useRef({ target: 0, value: 0, raf: 0, active: false, zoom: -1 })

  const [srcs] = useState(pickSources)
  const [ready, setReady] = useState(false)
  const [reduced, setReduced] = useState(false)
  const [beat, setBeat] = useState(0)

  // Both frames are decoded before the moment can be reached. A push-in that
  // arrives at an undecoded macro is the failure this preload exists to avoid.
  useEffect(() => {
    let live = true
    Promise.all(
      [srcs.wide, srcs.macro].map(
        (src) =>
          new Promise((resolve) => {
            const img = new Image()
            img.src = src
            const done = () => resolve()
            if (img.decode) img.decode().then(done, done)
            else {
              img.onload = done
              img.onerror = done
            }
          })
      )
    ).then(() => live && setReady(true))
    return () => {
      live = false
    }
  }, [srcs])

  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    const apply = () => setReduced(mq.matches)
    apply()
    mq.addEventListener('change', apply)
    return () => mq.removeEventListener('change', apply)
  }, [])

  useEffect(() => {
    const track = trackRef.current
    const frame = frameRef.current
    if (!track || !frame) return

    const st = stateRef.current

    // One authored value. Everything in the section reads from it and nothing
    // else, so the labels cannot drift away from the pixels they point at.
    const write = (p) => {
      const c = camera(p)
      const w = wideRef.current
      const m = macroRef.current
      if (w) {
        w.style.transform = `translate3d(${c.wide.x * 100}%, ${c.wide.y * 100}%, 0) scale(${c.zWide})`
        w.style.opacity = String(1 - c.macroOpacity)
      }
      if (m) {
        m.style.transform = `translate3d(${c.macro.x * 100}%, ${c.macro.y * 100}%, 0) scale(${c.zMacro})`
        m.style.opacity = String(c.macroOpacity)
      }

      const box = frame.getBoundingClientRect()
      const layerW = box.width
      const layerH = layerW * 0.5625
      const offsetY = (box.height - layerH) / 2

      for (const f of FEATURES) {
        const el = featureRefs.current[f.id]
        if (!el) continue
        // The label is placed from the same camera that moved the picture, so
        // it sits on the feature at every zoom rather than at a guessed spot.
        const fx = c.macro.x + f.x * c.zMacro
        const fy = c.macro.y + f.y * c.zMacro
        const inFrame = fx > 0.06 && fx < 0.94 && fy > 0.05 && fy < 0.95
        const shown = inFrame && c.e >= f.from && c.e < f.to
        el.style.transform = `translate3d(${fx * layerW}px, ${fy * layerH + offsetY}px, 0)`
        el.dataset.shown = shown ? 'true' : 'false'
      }

      const zoom = Math.round(c.zWide * 10) / 10
      if (zoom !== st.zoom && zoomRef.current) {
        st.zoom = zoom
        zoomRef.current.textContent = zoom.toFixed(1)
      }
      const next = c.e < 0.2 ? 0 : c.e < 0.62 ? 1 : c.e < 0.9 ? 2 : 3
      setBeat((prev) => (prev === next ? prev : next))
    }

    if (reduced) {
      write(REST_PROGRESS)
      const onResize = () => write(REST_PROGRESS)
      window.addEventListener('resize', onResize)
      return () => window.removeEventListener('resize', onResize)
    }

    const measure = () => {
      const rect = track.getBoundingClientRect()
      const span = rect.height - window.innerHeight
      st.target = span > 0 ? clamp(-rect.top / span) : 0
    }

    const tick = () => {
      // Smoothed toward the scroll position rather than snapped to it: the
      // push-in glides, and native scrolling is left alone.
      st.value += (st.target - st.value) * 0.14
      if (Math.abs(st.target - st.value) < 0.0004) st.value = st.target
      write(st.value)
      st.raf = st.active ? requestAnimationFrame(tick) : 0
    }

    const start = () => {
      if (st.active) return
      st.active = true
      st.raf = requestAnimationFrame(tick)
    }
    const stop = () => {
      st.active = false
      if (st.raf) cancelAnimationFrame(st.raf)
      st.raf = 0
    }

    const onScroll = () => {
      measure()
      start()
    }

    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          measure()
          start()
        } else {
          measure()
          st.value = st.target
          write(st.value)
          stop()
        }
      },
      { rootMargin: '20% 0px' }
    )
    io.observe(track)

    measure()
    st.value = st.target
    write(st.value)
    window.addEventListener('scroll', onScroll, { passive: true })
    window.addEventListener('resize', onScroll)
    return () => {
      io.disconnect()
      stop()
      window.removeEventListener('scroll', onScroll)
      window.removeEventListener('resize', onScroll)
    }
  }, [reduced, ready])

  return (
    <section
      className="approach"
      ref={trackRef}
      data-reduced={reduced ? 'true' : 'false'}
      aria-labelledby="approach-title"
    >
      <div className="approach__stage">
        <div className="approach__frame" ref={frameRef}>
          <div className="approach__layers" aria-hidden="true">
            <img className="approach__layer" ref={wideRef} src={srcs.wide} alt="" decoding="async" />
            <img className="approach__layer" ref={macroRef} src={srcs.macro} alt="" decoding="async" />
          </div>

          <p className="approach__alt">
            A 210mm kurouchi gyuto photographed whole, then at the heel: black forge scale across the
            upper blade, a bright hand-ground bevel along the edge, and an irregular line where the
            two meet.
          </p>

          <div className="approach__notes" aria-hidden="true">
            {FEATURES.map((f) => (
              <figure
                key={f.id}
                className={`note note--${f.side}`}
                data-shown="false"
                ref={(el) => {
                  featureRefs.current[f.id] = el
                }}
              >
                <span className="note__pin" />
                <figcaption className="note__body">
                  <span className="note__label">{f.label}</span>
                  <span className="note__text">{f.note}</span>
                </figcaption>
              </figure>
            ))}
          </div>

          <div className="approach__hud">
            <span className="hud__key">life size</span>
            <span className="hud__value">
              &times;<span ref={zoomRef}>1.0</span>
            </span>
          </div>

          <div className="approach__copy" data-beat={beat}>
            <p className="approach__eyebrow">Kaji No.7 &mdash; 210mm</p>
            <h1 className="approach__title" id="approach-title">
              <span>At arm&rsquo;s length</span>
              <span>every knife</span>
              <span>looks like this one.</span>
            </h1>
            <p className="approach__lede">
              So walk up to it. Nothing below is a photograph of a different knife &mdash; it is this
              one, closer.
            </p>
            <p className="approach__cue">Scroll</p>
          </div>

          <p className="approach__payoff" data-beat={beat}>
            Every mark you are looking at was put there by a person, one blade at a time. A factory
            grinds this face flat and identical, four thousand times a day, and there is nothing on
            it to look at. That is the &pound;280.
          </p>

          <p className="approach__credit">
            Moritaka Hamono gy&#363;t&#333;, photographed by Frank Schulenburg. CC&nbsp;BY-SA&nbsp;4.0,
            via Wikimedia Commons. Graded and re-framed for this page.
          </p>
        </div>
      </div>
      <div className="approach__loading" data-ready={ready ? 'true' : 'false'} aria-hidden="true" />
    </section>
  )
}

/* Kaji No.7 — signature moment.
   Colours are sampled from the photographs themselves: the ink of the forge
   scale, the bone of the ho-wood handle, the warm brown of the board. */

:root {
  --ink: #0b0c0c;
  --ink-2: #141615;
  --bone: #e9e3d6;
  --bone-dim: #a8a294;
  --steel: #8e948f;
  --ember: #c07a3c;
  --hair: rgb(233 227 214 / 0.16);
  --display: 'Iowan Old Style', 'Palatino Linotype', Palatino, 'Book Antiqua', Georgia, serif;
  --mono: ui-monospace, 'SF Mono', 'JetBrains Mono', Menlo, Consolas, monospace;
  --sans: 'Helvetica Neue', Inter, system-ui, -apple-system, sans-serif;
}

* {
  box-sizing: border-box;
}

html {
  background: var(--ink);
}

body {
  margin: 0;
  background: var(--ink);
  color: var(--bone);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

::selection {
  background: var(--ember);
  color: var(--ink);
}

/* ---- the track -------------------------------------------------------- */

.approach {
  position: relative;
  height: 560vh;
  background: var(--ink);
}

.approach[data-reduced='true'] {
  height: auto;
}

.approach__stage {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh;
  overflow: hidden;
}

.approach[data-reduced='true'] .approach__stage {
  position: static;
  height: 92vh;
}

.approach__frame {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: var(--ink);
}

/* ---- the two photographs ---------------------------------------------- */

.approach__layers {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
}

.approach__layer {
  position: absolute;
  top: 50%;
  left: 0;
  width: 100%;
  aspect-ratio: 16 / 9;
  translate: 0 -50%;
  transform-origin: 0 0;
  will-change: transform, opacity;
  backface-visibility: hidden;
  display: block;
}

/* The letterbox above and below the frame is part of the composition: it is
   what makes the picture read as a held frame rather than a background. */
.approach__frame::before,
.approach__frame::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  height: calc((100% - 56.25vw) / 2);
  background: var(--ink);
  z-index: 3;
  pointer-events: none;
}

.approach__frame::before {
  top: 0;
  border-bottom: 1px solid var(--hair);
}

.approach__frame::after {
  bottom: 0;
  border-top: 1px solid var(--hair);
}

/* ---- annotation ------------------------------------------------------- */

.approach__notes {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
}

.note {
  position: absolute;
  top: 0;
  left: 0;
  margin: 0;
  width: 0;
  height: 0;
  will-change: transform;
}

.note__pin,
.note__body {
  opacity: 0;
  transition: opacity 420ms cubic-bezier(0.22, 0.7, 0.25, 1),
    translate 520ms cubic-bezier(0.22, 0.7, 0.25, 1);
}

.note[data-shown='true'] .note__pin,
.note[data-shown='true'] .note__body {
  opacity: 1;
  translate: 0 0;
}

.note__pin {
  position: absolute;
  left: -5px;
  top: -5px;
  width: 10px;
  height: 10px;
  border: 1px solid var(--bone);
  border-radius: 50%;
  background: rgb(11 12 12 / 0.35);
  box-shadow: 0 0 0 1px rgb(11 12 12 / 0.55);
}

.note[data-shown='true'] .note__pin {
  animation: pin-settle 620ms cubic-bezier(0.22, 0.7, 0.25, 1) both;
}

@keyframes pin-settle {
  from {
    transform: scale(2.4);
    opacity: 0;
  }
  to {
    transform: scale(1);
    opacity: 1;
  }
}

.note__body {
  position: absolute;
  width: 21ch;
  display: block;
  padding-block: 2px;
  font-size: 0.78rem;
  line-height: 1.45;
  text-shadow: 0 1px 14px rgb(11 12 12 / 0.9), 0 1px 3px rgb(11 12 12 / 0.9);
}

.note--right .note__body {
  left: 22px;
  top: -10px;
  border-left: 1px solid var(--hair);
  padding-left: 12px;
  translate: -10px 0;
}

.note--left .note__body {
  right: 22px;
  top: -10px;
  text-align: right;
  border-right: 1px solid var(--hair);
  padding-right: 12px;
  translate: 10px 0;
}

.note__label {
  display: block;
  font-family: var(--mono);
  font-size: 0.62rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ember);
  margin-bottom: 4px;
}

.note__text {
  display: block;
  color: var(--bone);
}

/* ---- the magnification readout ---------------------------------------- */

.approach__hud {
  position: absolute;
  z-index: 5;
  left: clamp(18px, 3.4vw, 46px);
  bottom: clamp(18px, 3.4vw, 46px);
  display: flex;
  align-items: baseline;
  gap: 10px;
  font-family: var(--mono);
  color: var(--bone-dim);
}

.hud__key {
  font-size: 0.6rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.hud__value {
  font-size: 1.15rem;
  color: var(--bone);
  font-variant-numeric: tabular-nums;
}

/* ---- copy ------------------------------------------------------------- */

.approach__copy {
  position: absolute;
  z-index: 5;
  left: clamp(18px, 3.4vw, 46px);
  top: clamp(48px, 9vh, 104px);
  max-width: 30ch;
  transition: opacity 700ms ease, translate 900ms cubic-bezier(0.22, 0.7, 0.25, 1);
}

.approach__copy[data-beat='0'] {
  opacity: 1;
  translate: 0 0;
}

.approach__copy:not([data-beat='0']) {
  opacity: 0;
  translate: 0 -14px;
  pointer-events: none;
}

.approach__eyebrow {
  margin: 0 0 18px;
  font-family: var(--mono);
  font-size: 0.62rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--ember);
}

.approach__title {
  margin: 0;
  font-family: var(--display);
  font-weight: 400;
  font-size: clamp(2.1rem, 4.6vw, 4rem);
  line-height: 1.02;
  letter-spacing: -0.02em;
}

.approach__title span {
  display: block;
}

.approach__title span:last-child {
  font-style: italic;
  color: var(--steel);
}

.approach__lede {
  margin: 22px 0 0;
  max-width: 26ch;
  font-size: 0.92rem;
  line-height: 1.55;
  color: var(--bone-dim);
}

.approach__cue {
  margin: 34px 0 0;
  font-family: var(--mono);
  font-size: 0.6rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--bone-dim);
  display: flex;
  align-items: center;
  gap: 10px;
}

.approach__cue::after {
  content: '';
  width: 44px;
  height: 1px;
  background: linear-gradient(90deg, var(--bone-dim), transparent);
  transform-origin: 0 50%;
  animation: cue 2.6s cubic-bezier(0.5, 0, 0.5, 1) infinite;
}

@keyframes cue {
  0%,
  100% {
    transform: scaleX(0.35);
    opacity: 0.35;
  }
  45% {
    transform: scaleX(1);
    opacity: 1;
  }
}

.approach__payoff {
  position: absolute;
  z-index: 5;
  right: clamp(18px, 3.4vw, 46px);
  bottom: clamp(56px, 12vh, 116px);
  margin: 0;
  max-width: 33ch;
  text-align: right;
  font-family: var(--display);
  font-size: clamp(1rem, 1.35vw, 1.32rem);
  line-height: 1.5;
  text-shadow: 0 1px 18px rgb(11 12 12 / 0.9);
  transition: opacity 800ms ease, translate 1000ms cubic-bezier(0.22, 0.7, 0.25, 1);
  opacity: 0;
  translate: 0 16px;
  pointer-events: none;
}

.approach__payoff[data-beat='3'] {
  opacity: 1;
  translate: 0 0;
}

.approach__credit {
  position: absolute;
  z-index: 5;
  right: clamp(18px, 3.4vw, 46px);
  bottom: clamp(18px, 3.4vw, 46px);
  margin: 0;
  max-width: 40ch;
  text-align: right;
  font-family: var(--mono);
  font-size: 0.56rem;
  line-height: 1.6;
  letter-spacing: 0.04em;
  color: rgb(168 162 148 / 0.62);
}

/* Read by screen readers; the pictures themselves carry empty alt because the
   camera is decorative and this sentence is the content. */
.approach__alt {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* ---- loading ---------------------------------------------------------- */

.approach__loading {
  position: fixed;
  z-index: 20;
  top: 0;
  left: 0;
  height: 2px;
  width: 100%;
  transform-origin: 0 50%;
  background: linear-gradient(90deg, var(--ember), transparent);
  transition: opacity 500ms ease 200ms, scale 900ms cubic-bezier(0.22, 0.7, 0.25, 1);
  scale: 0.15 1;
}

.approach__loading[data-ready='true'] {
  opacity: 0;
  scale: 1 1;
}

/* ---- reduced motion: an authored still -------------------------------- */

@media (prefers-reduced-motion: reduce) {
  .approach__cue,
  .approach__cue::after {
    animation: none;
  }

  .note[data-shown='true'] .note__pin {
    animation: none;
  }

  .approach__copy:not([data-beat='0']) {
    opacity: 1;
    translate: 0 0;
  }

  .approach__payoff {
    opacity: 1;
    translate: 0 0;
    position: static;
    max-width: none;
    text-align: left;
    padding: 26px clamp(18px, 3.4vw, 46px) 0;
  }
}

/* ---- mobile ----------------------------------------------------------- */

@media (max-width: 720px) {
  .approach {
    height: 460vh;
  }

  /* The picture takes the top of the screen and the words sit under it, so the
     frame stays 16:9 instead of being cropped to a slot. */
  .approach__frame::before {
    height: 13vh;
  }

  .approach__frame::after {
    height: calc(87vh - 56.25vw);
    background: linear-gradient(180deg, var(--ink) 0%, var(--ink) 100%);
  }

  .approach__layer {
    top: calc(13vh + 28.125vw);
  }

  .approach__copy {
    top: auto;
    bottom: clamp(64px, 14vh, 150px);
    left: 20px;
    right: 20px;
    max-width: none;
  }

  .approach__title {
    font-size: clamp(1.9rem, 8.6vw, 2.6rem);
  }

  .approach__lede {
    max-width: 34ch;
  }

  .approach__payoff {
    left: 20px;
    right: 20px;
    bottom: clamp(58px, 13vh, 140px);
    max-width: none;
    text-align: left;
    font-size: 1.02rem;
  }

  .approach__credit {
    left: 20px;
    right: 20px;
    bottom: 16px;
    text-align: left;
    max-width: none;
  }

  .approach__hud {
    left: auto;
    right: 20px;
    top: calc(13vh - 26px);
    bottom: auto;
  }

  .note__body {
    width: 15ch;
    font-size: 0.68rem;
  }

  .note--right .note__body,
  .note--left .note__body {
    left: 16px;
    right: auto;
    text-align: left;
    border-right: 0;
    border-left: 1px solid var(--hair);
    padding-left: 9px;
    padding-right: 0;
  }
}

