/* A scrim, not a wash: it is heavy where the words are and clears entirely
   across the middle of the frame, so the blade is never sitting under a filter. */
.approach__scrim {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    linear-gradient(100deg, rgb(11 12 12 / 0.9) 0%, rgb(11 12 12 / 0.62) 22%, rgb(11 12 12 / 0) 48%),
    linear-gradient(0deg, rgb(11 12 12 / 0.78) 0%, rgb(11 12 12 / 0.2) 22%, rgb(11 12 12 / 0) 42%),
    radial-gradient(120% 80% at 50% 45%, rgb(11 12 12 / 0) 40%, rgb(11 12 12 / 0.5) 100%);
  transition: opacity 600ms ease;
}

/* Once the copy has gone and the picture is the whole argument, the scrim
